    \State $g^{x}_{t}\gets\nabla_{x}L(x_{t},y_{t})$,
          $g^{y}_{t}\gets\nabla_{y}L(x_{t},y_{t})$.
    \State $x_{t+1}\gets x_{t}+\eta\,g^{x}_{t}$.
    \State $y_{t+1}\gets y_{t}-\eta\,g^{y}_{t}$.
\EndFor
